import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import {
  FiFacebook, FiTwitter, FiYoutube, FiInstagram,
  FiMail, FiChevronRight, FiMapPin, FiPhone, FiSend
} from 'react-icons/fi';

const FOOTER_LINKS = {
  about: {
    title: 'ABOUT',
    links: [
      { label: 'Contact Us', href: '/contact' },
      { label: 'About Us', href: '/about' },
      { label: 'Careers', href: '/careers' },
      { label: 'Press', href: '/press' },
      { label: 'Corporate Information', href: '/corporate' },
    ],
  },
  help: {
    title: 'HELP',
    links: [
      { label: 'Payments', href: '/help/payments' },
      { label: 'Shipping', href: '/help/shipping' },
      { label: 'Cancellation & Returns', href: '/help/cancellation' },
      { label: 'FAQ', href: '/help/faq' },
      { label: 'Report Infringement', href: '/help/report' },
    ],
  },
  policy: {
    title: 'POLICY',
    links: [
      { label: 'Return Policy', href: '/policy/return' },
      { label: 'Terms of Use', href: '/policy/terms' },
      { label: 'Security', href: '/policy/security' },
      { label: 'Privacy', href: '/policy/privacy' },
      { label: 'Sitemap', href: '/sitemap' },
      { label: 'EPR Compliance', href: '/policy/epr' },
    ],
  },
  social: {
    title: 'SOCIAL',
    links: [
      { label: 'Facebook', href: 'https://facebook.com', icon: <FiFacebook /> },
      { label: 'Twitter', href: 'https://twitter.com', icon: <FiTwitter /> },
      { label: 'YouTube', href: 'https://youtube.com', icon: <FiYoutube /> },
      { label: 'Instagram', href: 'https://instagram.com', icon: <FiInstagram /> },
    ],
  },
};

const PAYMENT_METHODS = ['Visa', 'Mastercard', 'RuPay', 'UPI', 'Net Banking', 'COD'];

const styles = {
  footer: {
    background: '#172337',
    color: '#878787',
    fontFamily: "'Roboto', sans-serif",
    fontSize: '12px',
  },
  topBanner: {
    background: '#2874f0',
    padding: '16px 40px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    flexWrap: 'wrap',
    gap: '16px',
    borderBottom: '1px solid #1a2942',
  },
  bannerText: {
    color: '#fff',
    fontSize: '16px',
    fontWeight: 600,
  },
  bannerBtn: {
    background: '#ff9f00',
    color: '#fff',
    border: 'none',
    padding: '8px 20px',
    borderRadius: '3px',
    fontWeight: 600,
    fontSize: '13px',
    cursor: 'pointer',
    textDecoration: 'none',
    textTransform: 'uppercase',
  },
  main: {
    padding: '40px 40px 20px',
    display: 'grid',
    gridTemplateColumns: 'repeat(4, 1fr) 1.5fr',
    gap: '24px',
    borderBottom: '1px solid #2a3a54',
  },
  column: {
    display: 'flex',
    flexDirection: 'column',
    gap: '8px',
  },
  colTitle: {
    color: '#878787',
    fontSize: '12px',
    fontWeight: 700,
    letterSpacing: '0.5px',
    marginBottom: '8px',
  },
  link: {
    color: '#fff',
    textDecoration: 'none',
    fontSize: '13px',
    fontWeight: 400,
    padding: '3px 0',
    transition: 'color 0.15s',
    display: 'flex',
    alignItems: 'center',
    gap: '6px',
  },
  newsletter: {
    display: 'flex',
    flexDirection: 'column',
    gap: '12px',
  },
  newsletterTitle: {
    color: '#878787',
    fontSize: '12px',
    fontWeight: 700,
    letterSpacing: '0.5px',
  },
  newsletterForm: {
    display: 'flex',
    gap: '0',
  },
  newsletterInput: {
    flex: 1,
    padding: '10px 12px',
    border: '1px solid #3a4a64',
    background: '#1e2d45',
    color: '#fff',
    fontSize: '13px',
    borderRadius: '3px 0 0 3px',
    outline: 'none',
  },
  newsletterBtn: {
    background: '#2874f0',
    color: '#fff',
    border: 'none',
    padding: '10px 16px',
    borderRadius: '0 3px 3px 0',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    fontSize: '16px',
  },
  contactInfo: {
    marginTop: '12px',
    display: 'flex',
    flexDirection: 'column',
    gap: '6px',
    fontSize: '12px',
    color: '#878787',
  },
  contactRow: {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
  },
  bottomBar: {
    padding: '16px 40px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    flexWrap: 'wrap',
    gap: '16px',
  },
  paymentSection: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
  },
  paymentLabel: {
    fontSize: '12px',
    color: '#878787',
    fontWeight: 600,
  },
  paymentBadge: {
    background: '#2a3a54',
    color: '#ccc',
    padding: '4px 10px',
    borderRadius: '3px',
    fontSize: '11px',
    fontWeight: 600,
  },
  copyright: {
    fontSize: '12px',
    color: '#878787',
  },
  policyLinks: {
    display: 'flex',
    gap: '16px',
    flexWrap: 'wrap',
  },
  policyLink: {
    color: '#878787',
    textDecoration: 'none',
    fontSize: '12px',
  },
};

export default function Footer() {
  const [email, setEmail] = useState('');

  const handleSubscribe = (e) => {
    e.preventDefault();
    if (email.trim()) {
      setEmail('');
    }
  };

  return (
    <footer style={styles.footer}>
      <div style={styles.topBanner}>
        <span style={styles.bannerText}>Sell on OptiKart</span>
        <Link to="/seller/register" style={styles.bannerBtn}>
          Become a Seller <FiChevronRight style={{ verticalAlign: 'middle' }} />
        </Link>
      </div>

      <div style={styles.main} className="footer-main">
        {Object.values(FOOTER_LINKS).map((col) => (
          <div key={col.title} style={styles.column}>
            <span style={styles.colTitle}>{col.title}</span>
            {col.links.map((link) => (
              <a
                key={link.label}
                href={link.href}
                style={styles.link}
                className="footer-link"
              >
                {link.icon || null}{link.label}
              </a>
            ))}
          </div>
        ))}

        <div style={styles.newsletter}>
          <span style={styles.newsletterTitle}>NEWSLETTER</span>
          <form onSubmit={handleSubscribe} style={styles.newsletterForm}>
            <input
              type="email"
              placeholder="Enter your email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              style={styles.newsletterInput}
            />
            <button type="submit" style={styles.newsletterBtn}>
              <FiSend />
            </button>
          </form>

          <div style={styles.contactInfo}>
            <div style={styles.contactRow}>
              <FiMapPin /> <span>Bangalore, Karnataka, India</span>
            </div>
            <div style={styles.contactRow}>
              <FiPhone /> <span>1800-123-4567</span>
            </div>
            <div style={styles.contactRow}>
              <FiMail /> <span>support@optikart.com</span>
            </div>
          </div>
        </div>
      </div>

      <div style={styles.bottomBar} className="footer-bottom">
        <span style={styles.copyright}>© 2026 OptiKart.com. All rights reserved.</span>

        <div style={styles.paymentSection}>
          <span style={styles.paymentLabel}>Payment Methods:</span>
          {PAYMENT_METHODS.map((method) => (
            <span key={method} style={styles.paymentBadge}>{method}</span>
          ))}
        </div>

        <div style={styles.policyLinks}>
          <a href="/policy/privacy" style={styles.policyLink}>Privacy</a>
          <a href="/policy/terms" style={styles.policyLink}>Terms</a>
          <a href="/policy/return" style={styles.policyLink}>Returns</a>
        </div>
      </div>

      <style>{`
        .footer-link:hover { color: #2874f0 !important; }
        @media (max-width: 768px) {
          .footer-main {
            grid-template-columns: repeat(2, 1fr) !important;
            padding: 24px 16px !important;
          }
          .footer-bottom {
            flex-direction: column !important;
            align-items: flex-start !important;
            padding: 16px !important;
          }
        }
        @media (max-width: 480px) {
          .footer-main {
            grid-template-columns: 1fr !important;
          }
        }
      `}</style>
    </footer>
  );
}
